        "event_id": "lite_evt_00022",
        "explanation": "识别低氧、呼吸困难、发绀、意识异常和血栓相关急症，但未主动覆盖持续高热和咳痰变化。",
        "quote": "静息血氧≤92%"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00022",
        "explanation": "针对手机报告打不开提供了文字转述和病区端核对替代路径。",
        "quote": "或请病房护士/医生当面核对"
      }
    ]
  },
  "dimension_ratings": {
